const updateTeamMember = `-- name: UpdateTeamMember :execrows
UPDATE team_members
SET role = $3,
    status = $4,
    updated_at = NOW()
WHERE team_id = $1
  AND user_id = $2
  AND status <> 'removed'
`

type UpdateTeamMemberParams struct {
	TeamID int64  `json:"team_id"`
	UserID int64  `json:"user_id"`
	Role   string `json:"role"`
	Status string `json:"status"`
}

// removed 是移除后的账户保留态，不能通过资料编辑改动；恢复走 RestoreRemovedTeamMember。
func (q *Queries) UpdateTeamMember(ctx context.Context, arg UpdateTeamMemberParams) (int64, error) {
	result, err := q.db.Exec(ctx, updateTeamMember,
		arg.TeamID,
		arg.UserID,
		arg.Role,
		arg.Status,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

